import React, { useState } from 'react';

function AdminPanel({
  users = [],
  movies = [],
  showtimes = [],
  rooms = [],
  bookings = [],
  onCancelBooking,
  onCancelOrder,
  onAddShowtime,
  onBackHome,
}) {
  const [newShowtime, setNewShowtime] = useState({ movie_id: '', room_id: '', show_date: '', show_time: '', ticket_price: '' });

  const movieOptions = movies.map(movie => ({ value: movie.id, label: movie.title }));
  const roomOptions = rooms.map(room => ({ value: room.id, label: room.name }));

  const groupedBookings = bookings.reduce((acc, b) => {
    const key = b.original_booking_id || b.id;
    acc[key] = acc[key] || [];
    acc[key].push(b);
    return acc;
  }, {});

  const handleAddShowtime = (e) => {
    e.preventDefault();
    if (!newShowtime.movie_id || !newShowtime.room_id || !newShowtime.show_date || !newShowtime.show_time || !newShowtime.ticket_price) {
      alert('Vui lòng nhập đầy đủ thông tin suất chiếu.');
      return;
    }
    onAddShowtime({
      ...newShowtime,
      id: `st-${Date.now()}`,
      ticket_price: Number(newShowtime.ticket_price)
    });
    setNewShowtime({ movie_id: '', room_id: '', show_date: '', show_time: '', ticket_price: '' });
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h3 className="fw-bold mb-1" style={{ color: '#0047c3' }}>Bảng điều khiển quản trị</h3>
          <p className="text-secondary mb-0">Quản lý phim, suất chiếu và đơn vé theo thời gian thực.</p>
        </div>
        <button className="btn btn-secondary" style={{ borderRadius: 12 }} onClick={onBackHome}>Về trang chủ</button>
      </div>

      <div className="row gy-4">
        <div className="col-12 col-lg-4">
          <div className="card p-3 shadow-sm" style={{ borderRadius: 16 }}>
            <h5 className="fw-bold mb-3">Thống kê nhanh</h5>
            <div className="d-flex justify-content-between mb-2"><span>Người dùng</span><strong>{users.length}</strong></div>
            <div className="d-flex justify-content-between mb-2"><span>Phim</span><strong>{movies.length}</strong></div>
            <div className="d-flex justify-content-between mb-2"><span>Suất chiếu</span><strong>{showtimes.length}</strong></div>
            <div className="d-flex justify-content-between"><span>Đơn vé</span><strong>{Object.keys(groupedBookings).length}</strong></div>
          </div>
        </div>

        <div className="col-12 col-lg-8">
          <div className="card p-3 shadow-sm mb-4" style={{ borderRadius: 16 }}>
            <h5 className="fw-bold mb-3">Tạo suất chiếu mới</h5>
            <form onSubmit={handleAddShowtime}>
              <div className="row g-3">
                <div className="col-12 col-md-6">
                  <select className="form-select" value={newShowtime.movie_id} onChange={(e) => setNewShowtime(prev => ({ ...prev, movie_id: e.target.value }))}>
                    <option value="">Chọn phim</option>
                    {movieOptions.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                  </select>
                </div>
                <div className="col-12 col-md-6">
                  <select className="form-select" value={newShowtime.room_id} onChange={(e) => setNewShowtime(prev => ({ ...prev, room_id: e.target.value }))}>
                    <option value="">Chọn phòng</option>
                    {roomOptions.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                  </select>
                </div>
                <div className="col-6">
                  <input type="date" className="form-control" value={newShowtime.show_date} onChange={(e) => setNewShowtime(prev => ({ ...prev, show_date: e.target.value }))} />
                </div>
                <div className="col-6">
                  <input type="time" className="form-control" value={newShowtime.show_time} onChange={(e) => setNewShowtime(prev => ({ ...prev, show_time: e.target.value }))} />
                </div>
                <div className="col-12 col-md-6">
                  <input type="number" min="0" className="form-control" placeholder="Giá vé" value={newShowtime.ticket_price} onChange={(e) => setNewShowtime(prev => ({ ...prev, ticket_price: e.target.value }))} />
                </div>
                <div className="col-12 col-md-6 d-grid">
                  <button type="submit" className="btn btn-primary">Lưu suất chiếu</button>
                </div>
              </div>
            </form>
          </div>

          <div className="card p-3 shadow-sm" style={{ borderRadius: 16 }}>
            <h5 className="fw-bold mb-3">Danh sách đơn vé</h5>
            {Object.keys(groupedBookings).length === 0 && <p className="text-muted">Chưa có đơn vé nào.</p>}
            {Object.entries(groupedBookings).map(([groupId, group]) => {
              const first = group[0];
              return (
                <div key={groupId} className="border-bottom pb-3 mb-3">
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <div className="fw-bold">Đơn {groupId}</div>
                      <div className="text-secondary small">Người dùng: {users.find(u => u.id === first.user_id)?.username || 'Khách'}</div>
                      <div className="text-secondary small">Trạng thái: {first.paid ? 'Đã thanh toán' : 'Chưa thanh toán'}</div>
                    </div>
                    <div className="d-flex gap-2">
                      <button className="btn btn-sm btn-danger" onClick={() => onCancelOrder(groupId)}>Hủy đơn</button>
                    </div>
                  </div>
                  <div className="mt-2 small text-muted">Ghế: {group.map(b => b.seat_id).join(', ')}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminPanel;
